import numpy as np
from scipy.optimize import least_squares
y=dA_dt; v=np.var(y)
rng=np.random.default_rng(1)
def model(p):
    return (p[0]*t**p[1]*A**p[2]/(1+p[3]*A) + p[4]*t**p[5]*A**p[6]/(1+p[7]*A)
            + p[8]*t**p[9]*A**p[10])
best=(np.inf,None)
for _ in range(120):
    p0=np.r_[rng.normal(0,1,1),rng.uniform(0,2,1),rng.uniform(0,2,1),abs(rng.normal(0.5,0.5,1)),rng.normal(0,1,1),rng.uniform(0,2,1),rng.uniform(0,2,1),abs(rng.normal(0.5,0.5,1)),rng.normal(0,1,1),rng.uniform(0,2,1),rng.uniform(0,2,1)]
    try:
        r=least_squares(lambda p: model(p)-y, p0, max_nfev=1500)
        e=np.mean(r.fun**2)/v
        if np.isfinite(e) and e<best[0]: best=(e,r.x)
    except Exception: pass
print(best[0]); print(np.round(best[1],4))

